const item = $input.item;

if (!item.binary) {
  throw new Error('No binary found');
}

// helper: read text safely
function readText(binary) {
  if (!binary?.data) return null;
  return Buffer.from(binary.data, 'base64').toString('utf8');
}

// เตรียมที่เก็บ
item.json.text_files = {};

// loop ทุก binary ที่ upload มา
for (const [key, bin] of Object.entries(item.binary)) {
  const text = readText(bin);
  if (!text) continue;

  const name = (bin.fileName || key).toLowerCase();

  if (name.includes('elapsed') || name.includes('elasped')) {
    item.json.text_files.elapsed = text;
  } else if (name.includes('cpu')) {
    item.json.text_files.cpu = text;
  } else if (name.includes('io')) {
    item.json.text_files.io = text;
  }
}

// debug flag
item.json._step = 'text_extracted';

return item;

const item = $input.item;

if (!item.json?.text_files) {
  throw new Error('text_files not found');
}

// ---------- parser สำหรับ execplan ----------
function parseExecPlan(text) {
  const lines = text.split(/\r?\n/);
  const result = {};

  let currentSqlId = null;
  let buffer = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // format จริงของไฟล์คุณ
    // SQL_ID
    // 9q1vajrh586kj, child number 0
    if (line.trim() === 'SQL_ID') {
      const next = lines[i + 1] || '';
      const match = next.match(/^([a-z0-9]+),/i);

      if (match) {
        // save previous sql
        if (currentSqlId) {
          result[currentSqlId] = {
            plan_text: buffer.join('\n').trim()
          };
        }

        currentSqlId = match[1];
        buffer = [];
        i++; // skip next line
        continue;
      }
    }

    if (currentSqlId) {
      buffer.push(line);
    }
  }

  // last SQL
  if (currentSqlId) {
    result[currentSqlId] = {
      plan_text: buffer.join('\n').trim()
    };
  }

  return result;
}

// ---------- แยก 3 อัน ----------
const execplan_elapsed = item.json.text_files.elapsed
  ? parseExecPlan(item.json.text_files.elapsed)
  : {};

const execplan_cpu = item.json.text_files.cpu
  ? parseExecPlan(item.json.text_files.cpu)
  : {};

const execplan_io = item.json.text_files.io
  ? parseExecPlan(item.json.text_files.io)
  : {};

// ---------- output ----------
item.json.execplan_elapsed = execplan_elapsed;
item.json.execplan_cpu = execplan_cpu;
item.json.execplan_io = execplan_io;

item.json._step = 'execplan_split_3';

return item;

function parseUnit(s) {
  if (!s) return null;
  const t = String(s).trim().replace(/,/g, "");
  const m = t.match(/^(\d+(?:\.\d+)?)([KMG])?$/i);
  if (!m) return null;
  let v = parseFloat(m[1]);
  const u = (m[2] || "").toUpperCase();
  if (u === "K") v *= 1e3;
  if (u === "M") v *= 1e6;
  if (u === "G") v *= 1e9;
  return v;
}

function splitBlocks(text) {
  // จับหัวบล็อก SQL_ID ... child number ...
  const re = /SQL_ID\s+(\S+),\s*child number\s+(\d+)/g;
  const hits = [];
  let m;
  while ((m = re.exec(text)) !== null) {
    hits.push({ idx: m.index, sql_id: m[1], child: Number(m[2]) });
  }
  const blocks = [];
  for (let i = 0; i < hits.length; i++) {
    const start = hits[i].idx;
    const end = i + 1 < hits.length ? hits[i + 1].idx : text.length;
    blocks.push({
      sql_id: hits[i].sql_id,
      child_number: hits[i].child,
      raw_block: text.slice(start, end).trim(),
    });
  }
  return blocks;
}

function parseMultilineSection(lines, title) {
  const idx = lines.findIndex(l => l.trim().startsWith(title));
  if (idx === -1) return [];

  // ปกติ format จะเป็น:
  // Title
  // dashed line
  // blank line
  let i = idx + 3;

  const map = new Map(); // op_id -> text
  let curId = null;
  let buf = [];

  while (i < lines.length) {
    const peek = lines[i].trim();

    // เจอหัว section ใหม่/จบ
    if (
      peek.startsWith("Query Block Name") ||
      peek.startsWith("Predicate Information") ||
      peek.startsWith("Column Projection Information") ||
      peek.startsWith("NOTE:") ||
      peek.startsWith("Plan hash value:")
    ) break;

    const mm = lines[i].match(/^\s*(\d+)\s*-\s*(.+)$/);
    if (mm) {
      if (curId !== null) map.set(curId, buf.join(" ").trim());
      curId = Number(mm[1]);
      buf = [mm[2].trim()];
    } else {
      if (curId !== null) buf.push(lines[i].trim());
    }
    i++;
  }

  if (curId !== null) map.set(curId, buf.join(" ").trim());

  return [...map.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([op_id, text]) => ({ op_id, text }));
}

function parseQBAlias(lines) {
  const idx = lines.findIndex(l => l.trim().startsWith("Query Block Name / Object Alias"));
  if (idx === -1) return [];
  let i = idx + 3;

  const out = [];
  while (i < lines.length) {
    const t = lines[i].trim();
    if (
      t.startsWith("Predicate Information") ||
      t.startsWith("Column Projection Information") ||
      t.startsWith("NOTE:")
    ) break;

    const m = lines[i].match(/^\s*(\d+)\s*-\s*(.+)$/);
    if (m) {
      const op_id = Number(m[1]);
      const rest = m[2].trim();
      if (rest.includes(" / ")) {
        const [qb, alias] = rest.split(" / ", 2);
        out.push({ op_id, query_block: qb.trim(), object_alias: alias.trim() });
      } else {
        out.push({ op_id, query_block: rest, object_alias: null });
      }
    }
    i++;
  }
  return out;
}

function parsePlanTable(lines) {
  // helper: ตัดแค่ช่องว่างด้านขวา (ไม่แตะด้านซ้าย)
  const rtrim = (s) => String(s ?? "").replace(/[ \t]+$/g, "");

  // หา header ตารางแผนที่มี "| Id | Operation | ..."
  const headerIdx = lines.findIndex(l => l.includes("| Id") && l.includes("Operation"));
  if (headerIdx === -1) return null;

  const headerLine = lines[headerIdx];
  const cols = headerLine.trim()
    .replace(/^\|/, "")
    .replace(/\|$/, "")
    .split("|")
    .map(s => s.trim());

  // หลัง header จะมีเส้น dashed 1 บรรทัด
  let i = headerIdx + 2;

  const rows = [];
  while (i < lines.length) {
    const l = lines[i];
    const t = l.trim();

    // จบ table เมื่อเจอเส้น dashed ยาว (ก่อน section ถัดไป)
    if (t.startsWith("----")) break;
    if (!t.startsWith("|")) { i++; continue; }

    // ไม่ trim ทุกคอลัมน์ เพื่อให้ Operation เก็บ indent ได้
    let partsRaw = l
      .replace(/^\|/, "")
      .replace(/\|\s*$/, "")
      .split("|"); // ยังไม่ trim

    // บังคับให้จำนวนคอลัมน์เท่ากับ header
    if (partsRaw.length < cols.length) partsRaw = partsRaw.concat(Array(cols.length - partsRaw.length).fill(""));
    if (partsRaw.length > cols.length) partsRaw = partsRaw.slice(0, cols.length);

    const cells = {};
    for (let c = 0; c < cols.length; c++) {
      const label = cols[c];
      const seg = partsRaw[c] ?? "";

      // Operation: เก็บ leading spaces ไว้ (ตัดแค่ด้านขวา)
      // คอลัมน์อื่น trim ปกติ
      if (label === "Operation") cells[label] = rtrim(seg);
      else cells[label] = String(seg).trim();
    }

    const rawId = (cells["Id"] || "").trim();
    const hasStar = rawId.startsWith("*");
    const op_id_num = Number(rawId.replace("*", "").trim());

    rows.push({
      op_id: Number.isFinite(op_id_num) ? op_id_num : null,
      has_predicate_mark: hasStar,
      cells,
      est: {
        rows: parseUnit(cells["Rows"]),
        bytes: parseUnit(cells["Bytes"]),
      }
    });

    i++;
  }

  const headers = cols.map(label => ({
    key: label
      .toLowerCase()
      .replace(/\s*\(.*?\)\s*/g, "")
      .replace(/\s+/g, "_")
      .replace(/[^a-z0-9_]/g, ""),
    label
  }));

  return { headers, rows };
}

function parseOneBlock(raw_block) {
  const lines = raw_block.split(/\r?\n/);

  const sqlIdLine = lines.find(l => l.includes("SQL_ID"));
  const m = sqlIdLine?.match(/SQL_ID\s+(\S+),\s*child number\s+(\d+)/);
  const sql_id = m ? m[1] : null;
  const child_number = m ? Number(m[2]) : null;

  const noteLine = lines.find(l => l.trim().startsWith("NOTE:")) || null;
  const has_plan = !noteLine && raw_block.includes("Plan hash value:");

  // sql_text: จากหลัง "-----" (เส้นใต้หัว SQL_ID) จนถึง NOTE/PLAN_TABLE_OUTPUT/Plan hash
  let startSql = lines.findIndex(l => /^-+\s*$/.test(l.trim()));
  if (startSql === -1) startSql = 0;
  else startSql = startSql + 1;

  let cut = lines.findIndex(l => l.includes("Plan hash value:"));
  if (cut === -1) cut = lines.findIndex(l => l.trim().startsWith("NOTE:"));
  if (cut === -1) cut = lines.findIndex(l => l.includes("PLAN_TABLE_OUTPUT"));
  if (cut === -1) cut = lines.length;

  const sql_text = lines
    .slice(startSql, cut)
    .filter(l => l.trim() !== "")
    .join("\n")
    .trim();

  const plan_hash = (() => {
    const mm = raw_block.match(/Plan hash value:\s*(\d+)/);
    return mm ? Number(mm[1]) : null;
  })();

  const plan = has_plan ? {
    plan_hash_value: plan_hash,
    table: parsePlanTable(lines),
    qb_alias: parseQBAlias(lines),
    predicates: parseMultilineSection(lines, "Predicate Information"),
    projections: parseMultilineSection(lines, "Column Projection Information"),
  } : null;

  return {
    sql_id,
    child_number,
    has_plan,
    note: noteLine?.trim() || null,
    sql_text,
    plan
  };
}

// -------- main --------
const tf = $json.text_files || {};
const out = [];

for (const [metric, raw] of Object.entries(tf)) {
  const text = String(raw || "");
  const blocksRaw = splitBlocks(text);
  const blocks = blocksRaw.map(b => parseOneBlock(b.raw_block));

  out.push({
    json: {
      metric,                 // "io" | "cpu" | "elapsed"
      source_key: metric,     // เอาไว้ตั้งชื่อไฟล์ง่าย ๆ
      blocks_count: blocks.length,
      blocks
    }
  });
}

return out;

const item = $input.item;

// ตรวจว่ามี binary ไหม
if (!item.binary || !item.binary.html) {
  throw new Error('Binary html not found');
}

// แปลง base64 → string
const html = Buffer.from(
  item.binary.html.data,
  'base64'
).toString('utf-8');

// เพิ่ม field ใหม่
item.json.myNewField = 1;

// เก็บ html ลง json (ถ้าต้องใช้ต่อ)
item.json.html = html;

return item;

const html = $json.html;
if (!html) throw new Error('html not found');

// ---------- helper ----------
const clean = (s) =>
  s
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

// หา table หลังหัวข้อ
function extractTableAfter(titleText) {
  const idx = html.toLowerCase().indexOf(titleText.toLowerCase());
  if (idx === -1) return null;

  const after = html.slice(idx);
  return after.match(/<table[\s\S]*?<\/table>/i)?.[0] || null;
}

// parse table -> array of objects
function parseTop20(tableHtml) {
  if (!tableHtml) return [];

  // headers
  const headers = [...tableHtml.matchAll(/<th[^>]*>([\s\S]*?)<\/th>/gi)]
    .map(m => clean(m[1]));

  // rows
  const rows = [];
  const trs = [...tableHtml.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];

  trs.slice(1).forEach(tr => {
    const cells = [...tr[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)]
      .map(m => clean(m[1]));

    if (!cells.length) return;

    const row = {};
    cells.forEach((cell, i) => {
      const key = headers[i] || `col_${i}`;
      row[key] = cell;
    });

    rows.push(row);
  });

  return rows.slice(0, 20);
}

// ---------- extract 3 tables ----------
const result = {
  top20_elapsed_time: parseTop20(
    extractTableAfter('Top 20 SQL Statements (TOP 20 ELASPED TIME)')
  ),
  top20_most_cpu: parseTop20(
    extractTableAfter('Top 20 SQL Statements (TOP 20 MOST CPU)')
  ),
  top20_most_io: parseTop20(
    extractTableAfter('Top 20 SQL Statements (TOP 20 MOST I/O)')
  ),
};

// ---------- output ----------
return {
  json: result
};
/**
 * Map HTML + 3 TXT files เข้าด้วยกัน
 * ใช้ชื่อไฟล์เป็นตัวตัดสิน
 */

const output = {
  html: null,
  top20_elapsed_time: null,
  top20_most_cpu: null,
  top20_most_io: null
};

for (const item of $input.all()) {
  const binaries = item.binary || {};

  for (const [key, bin] of Object.entries(binaries)) {
    const filename = bin.fileName || '';

    // อ่าน content
    const content = Buffer.from(bin.data, 'base64').toString('utf8');

    // map ตามชื่อไฟล์
    if (filename.endsWith('.html')) {
      output.html = content;
    }

    if (filename.includes('Elapsed')) {
      output.top20_elapsed_time = JSON.parse(content);
    }

    if (filename.includes('CPU')) {
      output.top20_most_cpu = JSON.parse(content);
    }

    if (filename.includes('IO')) {
      output.top20_most_io = JSON.parse(content);
    }
  }
}

return [
  {
    json: output
  }
];

function toNum(v) {
  const s = String(v ?? "").trim();
  if (!s) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function detectMetricFromListName(listName) {
  const n = listName.toLowerCase();
  if (n.includes("elapsed")) return "elapsed";
  if (n.includes("cpu")) return "cpu";
  if (n.includes("io")) return "io";
  return "unknown";
}

const items = $input.all();

// 1) แยก execplan items กับ top20 item
const execItems = items.filter(it => it.json?.metric && Array.isArray(it.json?.blocks));
const topItem = items.find(it =>
  it.json?.top20_elapsed_time || it.json?.top20_most_cpu || it.json?.top20_most_io
);

if (!topItem) throw new Error("Top20 item not found (missing top20_* keys).");
if (execItems.length === 0) throw new Error("Execplan items not found (missing metric/blocks).");

// 2) ทำ index: metric -> { bySqlPlan, bySqlOnly }
const metricIndex = new Map();

for (const it of execItems) {
  const metric = String(it.json.metric);
  const blocks = it.json.blocks || [];

  const bySqlPlan = new Map(); // key = `${sql_id}|${plan_hash}`
  const bySqlOnly = new Map(); // key = sql_id -> blocks[]

  for (const b of blocks) {
    const sql_id = b.sql_id;
    if (!sql_id) continue;

    const plan_hash = b.plan?.plan_hash_value ?? null;

    if (plan_hash !== null) {
      bySqlPlan.set(`${sql_id}|${plan_hash}`, b);
    }

    if (!bySqlOnly.has(sql_id)) bySqlOnly.set(sql_id, []);
    bySqlOnly.get(sql_id).push(b);
  }

  metricIndex.set(metric, { bySqlPlan, bySqlOnly });
}

// 3) เลือก block ที่ดีที่สุดเวลามีหลายอัน
function pickBestBlock(blocks, planId) {
  if (!blocks || blocks.length === 0) return null;

  // ถ้ามี planId แล้ว ลองหาให้ตรงก่อน
  if (planId !== null && planId !== 0) {
    const exact = blocks.find(b => (b.plan?.plan_hash_value ?? null) === planId);
    if (exact) return exact;
  }

  // เอาตัวที่มี plan ก่อน
  const hasPlan = blocks.find(b => b.has_plan);
  if (hasPlan) return hasPlan;

  return blocks[0];
}

// 4) Enrich top20
const topJson = topItem.json;
const outTop = JSON.parse(JSON.stringify(topJson)); // deep clone

for (const [listName, rows] of Object.entries(outTop)) {
  if (!Array.isArray(rows)) continue;

  const metric = detectMetricFromListName(listName);
  const idx = metricIndex.get(metric);

  outTop[listName] = rows.map(r => {
    const sqlId = r["SQL ID"] || r["SQL_ID"] || r["sql_id"];
    const planId = toNum(r["Plan ID"] ?? r["PLAN_ID"] ?? r["plan_id"]);

    let block = null;

    if (idx && sqlId) {
      const { bySqlPlan, bySqlOnly } = idx;

      // match เป๊ะ sql+plan ก่อน
      if (planId !== null && planId !== 0) {
        block = bySqlPlan.get(`${sqlId}|${planId}`) || null;
      }

      // fallback: match sql อย่างเดียว
      if (!block) {
        const candidates = bySqlOnly.get(sqlId) || [];
        block = pickBestBlock(candidates, planId);
      }
    }

    return {
      ...r,
      execplan_metric: metric,
      execplan: block
        ? {
            sql_id: block.sql_id,
            child_number: block.child_number,
            has_plan: block.has_plan,
            note: block.note,
            sql_text: block.sql_text,

            plan_hash_value: block.plan?.plan_hash_value ?? null,
            table: block.plan?.table ?? null,
            predicates: block.plan?.predicates ?? [],
            projections: block.plan?.projections ?? [],
            qb_alias: block.plan?.qb_alias ?? []
          }
        : null
    };
  });
}

return [{ json: outTop }];

function classifyStatement(stmt="") {
  const s = stmt.trim().toLowerCase();
  if (/^(select|insert|update|delete)\b/.test(s)) return "DML";
  if (/^(declare|begin)\b/.test(s) || /\bcall\b/.test(s)) return "PLSQL";
  return "OTHER";
}

function hasWhere(stmt="") {
  return /\bwhere\b/i.test(stmt);
}

function isSystemOracle(stmt="") {
  return /\bdbms_/i.test(stmt) || /\bv\$/i.test(stmt) || /\bsys\./i.test(stmt) || /\bsystem\./i.test(stmt) || /\bdba_/i.test(stmt);
}

function likeValueBroken(stmt="") {
  return /\blike\s*=\b/i.test(stmt) || /\blike\s*$/i.test(stmt);
}

function analyzePlan(execplan) {
  const res = { hasTAF:false, tafTables:[], hasIndex:false };
  const rows = execplan?.table?.rows || [];

  for (const r of rows) {
    const op = String(r?.cells?.Operation ?? r?.cells?.OPERATION ?? "").toUpperCase();
    const name = String(r?.cells?.Name ?? r?.cells?.OBJECT_NAME ?? "").trim();

    if (op.includes("TABLE ACCESS FULL")) {
      res.hasTAF = true;
      if (name) res.tafTables.push(name);
    }
    if (op.includes("TABLE ACCESS BY INDEX") || op.includes("INDEX RANGE SCAN") || op.includes("INDEX UNIQUE SCAN")) {
      res.hasIndex = true;
    }
  }
  res.tafTables = [...new Set(res.tafTables)];
  return res;
}

function buildRecommendation(row) {
  const stmt = row.Statement || "";
  const type = classifyStatement(stmt);
  const rec = [];
  const codes = [];

  // LIKE หลุด
  if (likeValueBroken(stmt)) {
    rec.push("ตรวจสอบ SQL statement โดยละเอียดอีกครั้ง เนื่องจากพบเงื่อนไข LIKE แต่ไม่สามารถอ่านค่าที่เปรียบเทียบได้ครบถ้วนจากข้อมูลที่เก็บ");
    codes.push("LIKE_BROKEN");
  }

  // ไม่มี execplan / หา plan ไม่เจอ
  if (!row.execplan || row.execplan.has_plan === false) {
    if (type === "DML") {
      rec.push("ตรวจสอบ Execution plan โดยละเอียดอีกครั้ง เนื่องจากในช่วงที่ตรวจสอบ SQL_ID นี้ Execution plan ถูก Purge ออกจาก Library cache แล้ว");
      codes.push("DML_PLAN_PURGED");
    }
    return { type, rec, codes };
  }

  // มี execplan
  const { hasTAF, tafTables, hasIndex } = analyzePlan(row.execplan);
  const where = hasWhere(stmt);

  if (type === "DML") {
    if (hasTAF && !where) {
      rec.push("ไม่สามารถปรับแต่ง Execution plan ได้เนื่องจากไม่มี Criteria WHERE ในการค้นหา");
      codes.push("DML_TAF_NO_WHERE");
    } else if (hasTAF) {
      rec.push(`ตรวจพบ Operation Table Access Full ที่ ${tafTables.length ? tafTables.join(", ") : "<TABLE>"}`);
      rec.push("ตรวจสอบอีกครั้งว่าสามารถสร้าง INDEX เพื่อช่วยในการ Query ข้อมูลได้หรือไม่");
      codes.push("DML_TAF_FOUND");
    } else if (hasIndex) {
      rec.push("ไม่สามารถปรับแต่งเพิ่มเติมได้ เนื่องจากมีการเรียกใช้ INDEX อยู่แล้ว");
      codes.push("DML_INDEX_USED");
    } else {
      rec.push("ตรวจสอบอีกครั้งว่าสามารถสร้าง INDEX เพื่อช่วยในการ Query ข้อมูลได้หรือไม่");
      codes.push("DML_NO_TAF_NO_INDEX");
    }
  } else if (type === "PLSQL") {
    if (isSystemOracle(stmt)) {
      rec.push("SQL statement นี้เกี่ยวข้องกับการเก็บข้อมูลสถิติสำหรับ Oracle ซึ่งเป็นการทำงานตามปกติ");
      codes.push("PLSQL_ORACLE_STAT");
    } else if (/:([a-z]\w*)/i.test(stmt)) {
      rec.push("ตรวจสอบ Execution plan โดยละเอียดจาก Optimizer trace");
      codes.push("PLSQL_BIND_TRACE");
    }
  }

  return { type, rec, codes };
}

// -------- main --------
const input = $input.first().json;  // เพราะคุณมี 1 item
const out = JSON.parse(JSON.stringify(input));

for (const [k, arr] of Object.entries(out)) {
  if (!Array.isArray(arr)) continue;

  out[k] = arr.map(row => {
    const { type, rec, codes } = buildRecommendation(row);
    return {
      ...row,
      StatementType: type,
      Recommendation: rec,
      RecommendationCode: codes.join("|")
    };
  });
}

// สำคัญ: ต้องคืน array ของ items
return [{ json: out }];
